import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.BTg7EidG.js";const r="/athanor-docs/screens/encounter.png",s="/athanor-docs/screens/tactical.png",m=JSON.parse('{"title":"Battles & Dungeons","description":"","frontmatter":{},"headers":[],"relativePath":"guide/combat.md","filePath":"guide/combat.md"}'),i={name:"guide/combat.md"};function l(h,e,d,g,u,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="battles-dungeons" tabindex="-1">Battles &amp; Dungeons <a class="header-anchor" href="#battles-dungeons" aria-label="Permalink to &quot;Battles &amp; Dungeons&quot;">​</a></h1><h2 id="joining-battle" tabindex="-1">Joining battle <a class="header-anchor" href="#joining-battle" aria-label="Permalink to &quot;Joining battle&quot;">​</a></h2><p><img src="'+r+'" alt="An encounter"></p><p>March onto an enemy and the game pauses to ask how you want to fight: <strong>Trust the captains</strong> for a quick outcome, or <strong>⚔ Take the field</strong> to fight the battle yourself. You can also <strong>Fall back</strong>, unless you have been ambushed.</p><p>Before you choose, your captains size up the fight and say so plainly, from &quot;expect a rout&quot; down to &quot;counsel against this fight&quot;. When the counsel runs red, believe them.</p><p>Every engagement begins one of three ways. Ambushes either way are rare (a few percent, swayed by level difference — and rogue lords with the Ambush skill spring them more often):</p><ul><li><strong>Sprung ambush</strong> — you catch them unaware. On the field they stand asleep and take no turns until first struck.</li><li><strong>Battle</strong> — the sides face off and act in turns.</li><li><strong>Ambushed!</strong> — the enemy surrounds your party mid-field, and there is no declining the fight.</li></ul><h2 id="the-tactical-field" tabindex="-1">The tactical field <a class="header-anchor" href="#the-tactical-field" aria-label="Permalink to &quot;The tactical field&quot;">​</a></h2><p><img src="'+s+'" alt="A tactical battle"></p><p>Turns run by unit speed; each unit gets <strong>one move and one action</strong>. Blue tiles show where you can step. Tap one to preview the move (and the red reach it would give you), then confirm. Red tiles show your weapon&#39;s reach: adjacent for melee, three tiles for shooters. Heroes with <em>Transmute Blast</em> get a cast mode that burns half their Essence on one target. <em>Rally</em>, <em>Shield Wall</em> and <em>Overwhelm</em> all apply on the field, and <strong>Withdraw</strong> breaks off the fight. <strong>Home ground counts.</strong> A soldier fighting on their own guild&#39;s home terrain strikes and guards <strong>2 better</strong>; on their sworn rival&#39;s terrain, 2 worse. The pre-battle counsel tells you whose country you are standing in, and the battlefield&#39;s panel repeats it. Since a rival&#39;s ground also costs double to march across, invading a rival is hard in both senses.</p><p>The field itself is the country you fight in: forests and marshes give thick cover, sand and ice give almost none, and highlands and broken country climb in hills and crags where a marsh lies flat.</p><p>Pinch to zoom into the melee and drag to pan while zoomed, or use the <strong>+ / − / ⤢</strong> pad in the corner.</p><h2 id="high-ground-and-hard-landings" tabindex="-1">High ground and hard landings <a class="header-anchor" href="#high-ground-and-hard-landings" aria-label="Permalink to &quot;High ground and hard landings&quot;">​</a></h2><p>No field is flat. The ground rises in half-step ramps toward hills and crags, and boulders squat on the low ground where nothing can walk. Use them:</p><ul><li><strong>Shooters reach one tile further for every full height</strong> they hold above their target. A bowman on a crag commands the valley.</li><li>Half-step ramps climb free. A <strong>full-height jump</strong> up costs an extra move point, and nothing on foot climbs more than one full height in a step.</li><li>You can leap <strong>down</strong> any distance, but a plunge past three heights deals fall damage on the landing (the move preview warns you first). A fall bruises; it never kills outright.</li><li><strong>Winged creatures</strong> such as the Chimera ignore all of it: heights, ramps, falls.</li><li>Boulders block the charge. Put one between your archer and a foe&#39;s sword and make them walk the long way around.</li></ul><h2 id="dungeon-floors" tabindex="-1">Dungeon floors <a class="header-anchor" href="#dungeon-floors" aria-label="Permalink to &quot;Dungeon floors&quot;">​</a></h2><p>Garrisoned buildings fight <strong>floor by floor</strong> — the defenders split across the building&#39;s floors, and the <strong>STAIR DOWN</strong> hatch is visible on the far side of every hall. Clear the floor and the stair lights up: descend and fight on. With a <strong>rogue hero</strong> you have two more options:</p><ul><li><strong>Sneak past</strong> the next floor at the door — 25–75% by level. Fail, and that floor falls on you as an ambush.</li><li><strong>Flee down mid-fight</strong> — the whole party runs for the stair, eating parting blows based on how close the enemies stand and how fast each runner is. Slow units can die on the stairs.</li></ul><h2 id="the-prize-at-the-bottom" tabindex="-1">The prize at the bottom <a class="header-anchor" href="#the-prize-at-the-bottom" aria-label="Permalink to &quot;The prize at the bottom&quot;">​</a></h2><p>Every stormed hold ends in a prize: a <strong>chest</strong> of coin and stores scaled by how deep you fought, an <strong>artifact</strong> — finer the closer to the world&#39;s blighted heart — or, rarely, a <strong>caged hero</strong> who joins their rescuer. Victors also strip the fallen of their gear, and beaten marauder garrisons often guarded a hoard.</p>',20)])])}const p=t(i,[["render",l]]);export{m as __pageData,p as default};
